.hesperiden.tparrows {
	cursor:pointer;
	background:##bg-color##;
	width:##bg-size##px;
	height:##bg-size##px;
	position:absolute;
	display:block;
	z-index:1000;
    border-radius: 50%;
}
.hesperiden.tparrows.rs-touchhover {
	background:##hover-bg-color##;
}
.hesperiden.tparrows:before {
	font-family: 'revicons';
	font-size:##arrow-size##px;
	color:##arrow-color##;
	display:block;
	line-height: ##bg-size##px;
	text-align: center;
}
.hesperiden.tparrows.tp-leftarrow:before {
	content: '##left-icon##';
    margin-left:-3px;
}
.hesperiden.tparrows.tp-rightarrow:before {
	content: '##right-icon##';
    margin-right:-3px;
}
